  issue)
    sub="$1"; shift || true
    case "$sub" in
      list)
        jqf="."
        while [ $# -gt 0 ]; do
          case "$1" in
            --jq) jqf="$2"; shift 2 ;;
            --repo|--state|--label|--limit) shift 2 ;;
            --json) shift 2 ;;
            *) shift ;;
