#!/usr/bin/env bash
if [ "\\${1:-}" = "-i" ]; then
  echo "sed: -i requires an explicit backup-suffix argument on BSD (suffix-less -i is GNU-only)" >&2
  exit 1
fi
exec "\\$(PATH="\\${PATH#*:}" command -v sed)" "\\$@"
''';

